        while (sc.hasNextInt()) {
            ans.add(sc.nextInt());
        }

        List<Integer> res = new ArrayList<>();
        int n = ans.size();

        int pos = -1;
        int minValue = Integer.MAX_VALUE;

        // 查找最小的叶子节点值位置
        for (int i = 0; i < n; i++) {
            int leftIndex = 2 * (i + 1) - 1;
            int rightIndex = 2 * (i + 1);
            if (ans.get(i) == -1) {
                continue;
            }

            // 判断是否是叶子节点
            if (judge(ans, leftIndex) && judge(ans, rightIndex)) {
                if (ans.get(i) < minValue) {
                    pos = i;
                    minValue = ans.get(i);
                }
            }
        }

        // 从叶子节点到根节点
        while (pos != 0) {
            res.add(ans.get(pos));
            pos = (pos - 1) / 2;
