function computeHeight(N) {
    return Math.ceil(Math.log2(N + 1));
}
​
// 判断是否是叶子节点
function judge(ans, pos) {
    return pos >= ans.length || ans[pos] === -1;
}
​
function main() {
    // 读取输入并将其拆分为整数数组
    let input = '';
    let stdin = process.stdin;
    stdin.setEncoding('utf-8');
    stdin.on('data', function (data) {
        input += data;
    });
​
    stdin.on('end', function () {
        // 分割输入的字符串并转为整数数组
        const ans = input.trim().split(/\s+/).map(Number);
​
        let res = [];
        const n = ans.length;
​
        // 最小叶子节点值位置
        let pos = -1;
        let minValue = Infinity;
​
        // 查找最小叶子节点值的位置
        for (let i = 0; i < n; i++) {
            let leftIndex = 2 * (i + 1) - 1;
            let rightIndex = 2 * (i + 1);
​
            if (ans[i] === -1) {
                continue;
            }
​
            // 判断是否是叶子节点
            if (judge(ans, leftIndex) && judge(ans, rightIndex)) {
                if (ans[i] < minValue) {
                    pos = i;
                    minValue = ans[i];
                }
            }
        }
​
        // 从叶子节点到根节点
        while (pos !== 0) {
            res.push(ans[pos]);
            pos = Math.floor((pos - 1) / 2);
        }
        res.push(ans[0]);
​
        // 输出结果
        console.log(res.reverse().join(' '));
