package main
​
import (
    "bufio"
    "fmt"
    "math"
    "os"
    "strconv"
    "strings"
)
​
​
​
// 判断是否叶子节点
func judge(ans []int, pos int) bool {
    return pos >= len(ans) || ans[pos] == -1
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)

    scanner.Scan()
    input := scanner.Text()
    inputs := strings.Fields(input)
​
    // 将输入的字符串转换为整数数组
    var ans []int
    for _, val := range inputs {
        num, err := strconv.Atoi(val)
        if err != nil {
            fmt.Println("输入无效")
            return
        }
        ans = append(ans, num)
    }
​
    var res []int
    pos := -1 // 最小叶子节点的位置
    minValue := math.MaxInt // 初始化最小值为最大整数
​
    // 找到最小叶子节点的位置
    for i := 0; i < len(ans); i++ {
        leftIndex := 2*(i+1) - 1 // 左子节点索引
        rightIndex := 2*(i+1)    // 右子节点索引
        if ans[i] == -1 {
            continue
        }
        // 判断当前节点是否为叶子节点
        if judge(ans, leftIndex) && judge(ans, rightIndex) {
            if ans[i] < minValue {
                pos = i
                minValue = ans[i]
            }
        }
    }
​
    // 从叶子节点回溯到根节点，收集路径上的值
    for pos != 0 {
        res = append(res, ans[pos])
        pos = (pos - 1) / 2
    }
    res = append(res, ans[0]) // 添加根节点的值
​
    // 按从根节点到叶子节点的顺序输出路径
    for i := len(res) - 1; i >= 0; i-- {
        fmt.Print(res[i])
        if i != 0 {
            fmt.Print(" ")
        }
    }
}
